-- PREMIUM FLAGSHIP SMARTPHONES (10 products)
('samsung-galaxy-s25-fe-5g', 'Samsung Galaxy S25 FE 5G 8GB/256GB - Graphite', 'smartphones', 580000, 569000, 495000, 20, 0.19, '/assets/products/samsung-s25-fe.jpg', 'Flagship DNA distilled to its purest essentials. The S25 FE inherits the S25''s Dynamic AMOLED display, Snapdragon 8 Gen 3 for Galaxy processor, and pro-grade camera system, delivering a premium experience without the premium price tag.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/samsung-s25-fe.jpg', 535000, 4.7, 1, 'Samsung', 1, 1),

('google-pixel-10-pro', 'Google Pixel 10 Pro 5G 12GB/256GB - Porcelain White', 'smartphones', 850000, 829000, 720000, 12, 0.19, '/assets/products/pixel-10-pro.jpg', 'Google''s most intelligent phone yet. The Tensor G5 chip powers groundbreaking AI features including real-time language interpretation, Magic Editor 3.0 with generative fill, and a triple camera system co-designed with professional photographers.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/pixel-10-pro.jpg', 780000, 4.8, 1, 'Google', 1, 1),

('oneplus-13-pro', 'OnePlus 13 Pro 5G 16GB/512GB - Eternal Green', 'smartphones', 950000, 929000, 810000, 10, 0.22, '/assets/products/oneplus-13-pro.jpg', 'Never Settle reaches its zenith. The OnePlus 13 Pro features a 6.82" QHD+ LTPO 4.0 display, a Hasselblad-tuned quad-camera system with periscope zoom, and 150W SUPERVOOC charging that fills the 5,400mAh battery in just 18 minutes.', 1, unixepoch('2026-06-16'), 1, 810000, '/assets/products/oneplus-13-pro.jpg', 880000, 4.8, 1, 'OnePlus', 1, 1),

('xiaomi-16-ultra', 'Xiaomi 16 Ultra 5G 16GB/1TB - Ceramic White', 'smartphones', 1850000, 1790000, 1580000, 5, 0.23, '/assets/products/xiaomi-16-ultra.jpg', 'The pinnacle of Xiaomi engineering. A 1-inch Sony LYT-900 sensor co-developed with Leica captures studio-quality portraits, while the Snapdragon 8 Gen 5 chip, 6.81" WQHD+ AMOLED, and 120W wireless charging place it among the greatest phones ever made.', 1, unixepoch('2026-06-16'), 1, 1580000, '/assets/products/xiaomi-16-ultra.jpg', 1680000, 4.8, 0, 'Xiaomi', 1, 1),

('oppo-find-x8-ultra', 'OPPO Find X8 Ultra 5G 16GB/512GB - Ocean Wave Blue', 'smartphones', 1250000, 1215000, 1050000, 8, 0.22, '/assets/products/oppo-find-x8-ultra.jpg', 'The dual periscope camera system sets a new standard for mobile photography. With 3x and 6x optical zoom, a 1-inch main sensor, and MariSilicon Y imaging chip, the Find X8 Ultra captures breathtaking photos that rival professional cameras.', 1, unixepoch('2026-06-16'), 1, 1050000, '/assets/products/oppo-find-x8-ultra.jpg', 1150000, 4.7, 0, 'OPPO', 1, 1),

('huawei-pura-80-ultra', 'Huawei Pura 80 Ultra 5G 16GB/1TB - Rococo Gold', 'smartphones', 1650000, 1590000, 1380000, 5, 0.22, '/assets/products/huawei-pura-80-ultra.jpg', 'A masterpiece of optical engineering. The retractable 1-inch main camera with physical variable aperture (f/1.4-f/4.0) and 10x optical periscope zoom redefines what a smartphone camera can achieve, all powered by the Kirin 9100 processor.', 1, unixepoch('2026-06-16'), 1, 1380000, '/assets/products/huawei-pura-80-ultra.jpg', 1490000, 4.8, 0, 'Huawei', 1, 1),

('asus-zenfone-13-ultra', 'ASUS Zenfone 13 Ultra 5G 12GB/512GB - Midnight Eclipse', 'smartphones', 780000, 769000, 665000, 10, 0.20, '/assets/products/zenfone-13-ultra.jpg', 'Compact flagship perfection for those who refuse to compromise. The Zenfone 13 Ultra packs a 6.3" AMOLED 165Hz display, Snapdragon 8 Gen 5, and a versatile triple camera into a remarkably compact 180g body with a 3.5mm headphone jack.', 1, unixepoch('2026-06-16'), 1, 665000, '/assets/products/zenfone-13-ultra.jpg', 725000, 4.6, 0, 'ASUS', 1, 1),

('motorola-razr-60-ultra', 'Motorola Razr 60 Ultra 5G 12GB/512GB - Hot Pink', 'smartphones', 850000, 829000, 720000, 8, 0.19, '/assets/products/razr-60-ultra.jpg', 'The most iconic flip phone, reborn. The Razr 60 Ultra features the largest cover display on any flip phone at 4.2 inches, a gapless hinge rated for 600,000 folds, and a dual-camera system that takes stunning selfies using the main sensors.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/razr-60-ultra.jpg', 780000, 4.6, 1, 'Motorola', 1, 1),

('nothing-phone-3-pro', 'Nothing Phone 3 Pro 5G 12GB/512GB - Dark Matter Black', 'smartphones', 580000, 569000, 495000, 12, 0.20, '/assets/products/nothing-phone-3-pro.jpg', 'The Glyph Interface evolves with programmable LED zones that pulse to music, indicate timers, and display essential notifications. Beneath the transparent design lies a Snapdragon 8 Gen 5, a 50MP triple camera, and Nothing OS 3.0 with AI enhancements.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/nothing-phone-3-pro.jpg', 535000, 4.6, 1, 'Nothing', 1, 1),

('tecno-phantom-x5-ultra', 'Tecno Phantom X5 Ultra 5G 16GB/1TB - Nebula Silver', 'smartphones', 750000, 729000, 635000, 8, 0.21, '/assets/products/tecno-phantom-x5-ultra.jpg', 'Tecno''s boldest statement yet. The Phantom X5 Ultra features a revolutionary retractable portrait lens, a 6.9" LTPO AMOLED with 144Hz refresh, and 120W wired charging with 50W wireless, proving that African innovation competes on the global stage.', 1, unixepoch('2026-06-16'), 1, 635000, '/assets/products/tecno-phantom-x5-ultra.jpg', 695000, 4.7, 1, 'Tecno', 1, 1),

-- PREMIUM TABLETS & 2-IN-1 DEVICES (8 products)
('microsoft-surface-pro-11', 'Microsoft Surface Pro 11 Intel Core Ultra 7 16GB/1TB - Platinum', 'tablets', 1450000, 1420000, 1250000, 6, 0.89, '/assets/products/surface-pro-11.jpg', 'The most powerful Surface Pro ever built. The 13-inch PixelSense Flow display with 120Hz refresh, Thunderbolt 5 ports, and AI-accelerated Windows 12 make this the definitive 2-in-1 for professionals who demand laptop performance and tablet versatility.', 1, unixepoch('2026-06-16'), 1, 1250000, '/assets/products/surface-pro-11.jpg', 1350000, 4.7, 1, 'Microsoft', 1, 1),

('samsung-galaxy-tab-s11-plus', 'Samsung Galaxy Tab S11+ 12.4" 12GB/512GB 5G - Beige', 'tablets', 950000, 929000, 810000, 8, 0.57, '/assets/products/tab-s11-plus.jpg', 'The ultimate Android tablet for creative professionals. The 12.4-inch Dynamic AMOLED 2X display with 120Hz, S Pen with 2.8ms latency, and DeX mode transforms this tablet into a full desktop workstation. IP68 water and dust resistant.', 1, unixepoch('2026-06-16'), 1, 810000, '/assets/products/tab-s11-plus.jpg', 880000, 4.8, 1, 'Samsung', 1, 1),

('apple-ipad-mini-8-pro', 'Apple iPad mini 8 Pro 8.3" M3 Chip 256GB - Space Grey', 'tablets', 580000, 569000, 495000, 10, 0.30, '/assets/products/ipad-mini-8-pro.jpg', 'Pro-level power in the most portable iPad. The M3 chip, ProMotion 120Hz display, Apple Pencil Pro support, and all-day battery life make this the ultimate device for note-taking, sketching, and reading—all in a form factor that fits in one hand.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/ipad-mini-8-pro.jpg', 535000, 4.7, 1, 'Apple', 1, 1),

('lenovo-tab-extreme-gen-2', 'Lenovo Tab Extreme Gen 2 14.5" 16GB/512GB - Storm Grey', 'tablets', 750000, 729000, 635000, 6, 0.74, '/assets/products/lenovo-tab-extreme-2.jpg', 'A desktop-class Android tablet with a 14.5-inch 3K OLED 120Hz display, MediaTek Dimensity 9400, and a dual-mode Lenovo Precision Pen 4. The included keyboard case and kickstand make it a genuine laptop replacement for creative professionals.', 1, unixepoch('2026-06-16'), 1, 635000, '/assets/products/lenovo-tab-extreme-2.jpg', 695000, 4.6, 0, 'Lenovo', 1, 1),

('oneplus-pad-3-pro', 'OnePlus Pad 3 Pro 12.1" 16GB/512GB 5G - Halo Green', 'tablets', 480000, 469000, 410000, 10, 0.55, '/assets/products/oneplus-pad-3-pro.jpg', 'OnePlus brings its fast and smooth philosophy to tablets. The 12.1-inch 144Hz 3K display, Snapdragon 8 Gen 5, and OnePlus Stylo 2 with 2ms latency make this the go-to tablet for content creators who need speed and precision.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/oneplus-pad-3-pro.jpg', 438000, 4.6, 1, 'OnePlus', 1, 1),

('amazon-fire-max-13-pro', 'Amazon Fire Max 13 Pro 256GB with Keyboard & Stylus Bundle', 'tablets', 320000, 315000, 268000, 12, 0.82, '/assets/products/fire-max-13-pro.jpg', 'Amazon''s most powerful tablet gets a productivity overhaul. The 13-inch 2.5K display, octa-core processor, and included keyboard case and stylus make this an affordable alternative to premium tablets for students, writers, and business users.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/fire-max-13-pro.jpg', 298000, 4.4, 1, 'Amazon', 1, 1),

('reMarkable-3-paper-tablet', 'reMarkable 3 Paper Tablet with Marker Plus - 10.3" Canvas Display', 'tablets', 480000, 469000, 410000, 6, 0.40, '/assets/products/remarkable-3.jpg', 'Distraction-free focus in a digital world. The reMarkable 3 features a new textured Canvas Color display that reproduces the tactile sensation of paper, 8 weeks of battery life, and AI-powered handwriting recognition that converts notes to typed text.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/remarkable-3.jpg', 438000, 4.6, 0, 'reMarkable', 1, 1),

('huawei-matepad-pro-14-2', 'Huawei MatePad Pro 14.2" OLED Flex 12GB/512GB - Golden Black', 'tablets', 680000, 659000, 575000, 5, 0.58, '/assets/products/huawei-matepad-pro.jpg', 'A stunning 14.2-inch flexible OLED that bends to reduce glare and reflections. The Kirin 9100 processor, M-Pencil 4 with NearLink technology, and HarmonyOS 5 create a seamless ecosystem for artists, designers, and professionals.', 1, unixepoch('2026-06-16'), 1, 575000, '/assets/products/huawei-matepad-pro.jpg', 625000, 4.7, 0, 'Huawei', 1, 1),

