('ring-alarm-pro-2', 'Ring Alarm Pro 2 14-Piece Whole-Home Security Kit with eero WiFi 7', 'smart-home', 380000, 369000, 315000, 8, 3.5, '/assets/products/ring-alarm-pro-2.jpg', 'A complete security system with a built-in WiFi 7 router. The Alarm Pro 2 protects your entire home with 14 pieces including door/window sensors, motion detectors, a keypad, and a siren, while ensuring your internet stays fast with eero mesh technology.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/ring-alarm-pro-2.jpg', 348000, 4.6, 1, 'Ring', 1, 1),

('eufy-security-s380-homebase', 'eufy Security S380 HomeBase 3 with 4-Camera 4K System', 'smart-home', 520000, 509000, 445000, 6, 4.8, '/assets/products/eufy-s380-system.jpg', 'Local AI-powered security with no monthly fees. The HomeBase 3 processes video with a neural processing unit that distinguishes family from strangers, vehicles from animals, and stores 1TB of encrypted footage locally—your data never leaves your home.', 1, unixepoch('2026-06-16'), 1, 445000, '/assets/products/eufy-s380-system.jpg', 485000, 4.7, 1, 'eufy', 1, 1),

('arlo-pro-6-xl-spotlight', 'Arlo Pro 6 XL Wireless Floodlight Camera 2K - Twin Pack', 'smart-home', 320000, 315000, 268000, 8, 2.1, '/assets/products/arlo-pro6-xl.jpg', 'Deter intruders with 2,500 lumens of motion-activated light and a built-in 110dB siren. Each camera features 2K HDR video, color night vision, and a 12-month battery life per charge. Wire-free installation takes minutes, not hours.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/arlo-pro6-xl.jpg', 298000, 4.5, 0, 'Arlo', 1, 1),

('google-nest-doorbell-wired-3', 'Google Nest Doorbell Wired 3rd Gen with 24/7 Recording', 'smart-home', 185000, 179000, 148000, 15, 0.38, '/assets/products/nest-doorbell-3.jpg', 'Never miss a moment with continuous 24/7 recording. The wired Nest Doorbell 3 features HDR video, 3 hours of free event history, intelligent alerts that distinguish people, packages, animals, and vehicles, and seamless Google Home integration.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/nest-doorbell-3.jpg', 168000, 4.6, 1, 'Google', 1, 1),

('reolink-trackmix-wifi-6', 'Reolink TrackMix WiFi 6 Dual-Lens 4K PTZ Camera with Auto-Zoom', 'smart-home', 165000, 159000, 132000, 12, 0.85, '/assets/products/reolink-trackmix.jpg', 'Two lenses working as one for unbeatable coverage. The wide-angle lens monitors the full scene while the telephoto lens auto-zooms and tracks any moving person or vehicle, ensuring you capture every detail. Solar panel ready for wire-free installation.', 1, unixepoch('2026-06-16'), 1, 132000, '/assets/products/reolink-trackmix.jpg', 149000, 4.5, 1, 'Reolink', 1, 1),

('switchbot-smart-lock-ultra', 'SwitchBot Smart Lock Ultra with Matter & Facial Recognition', 'smart-home', 165000, 159000, 132000, 10, 0.45, '/assets/products/switchbot-lock-ultra.jpg', 'Transform any deadbolt into a smart lock in seconds without removing your existing hardware. The Lock Ultra adds facial recognition via an integrated camera, fingerprint unlocking, and Matter-over-Thread support for seamless smart home integration.', 1, unixepoch('2026-06-16'), 1, 132000, '/assets/products/switchbot-lock-ultra.jpg', 149000, 4.5, 1, 'SwitchBot', 1, 1),

('aqara-curtain-driver-e3', 'Aqara Curtain Driver E3 Motorized Rod with Solar Panel', 'smart-home', 85000, 82900, 68000, 15, 0.55, '/assets/products/aqara-curtain-e3.jpg', 'Automate your curtains without replacing your rods. The E3 clamps onto existing rod-style curtains and opens or closes them on schedule, via voice, or based on sunlight. The integrated solar panel keeps the battery charged indefinitely.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/aqara-curtain-e3.jpg', 78000, 4.4, 0, 'Aqara', 1, 1),

