('gotrax-gxl-v3', 'GoTrax GXL V3 Electric Scooter 20km Range - Matte Black', 'e-mobility', 185000, 179000, 148000, 15, 13.5, '/assets/products/gotrax-gxl-v3.jpg', 'The most affordable quality electric scooter for short Nigerian commutes. The GXL V3 features a 250W motor reaching 25km/h, 8.5-inch pneumatic tires for uneven roads, and a quick-folding mechanism. Perfect for campus, estates, and last-mile travel.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/gotrax-gxl-v3.jpg', 168000, 4.3, 1, 'GoTrax', 1, 1),

('niu-kqi-300x', 'NIU KQi 300X Electric Scooter with NFC & App Control - White', 'e-mobility', 250000, 245000, 215000, 10, 18.8, '/assets/products/niu-kqi300x.jpg', 'Smart mobility from the world''s leading electric scooter brand. The KQi 300X features NFC unlocking, a bright halo headlight, regenerative braking, and NIU''s battery management system with 12 protection circuits for absolute safety during charging.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/niu-kqi300x.jpg', 235000, 4.5, 0, 'NIU', 1, 1),

('hover-1-journey-max', 'Hover-1 Journey Max Folding Electric Scooter 24km Range - Blue', 'e-mobility', 150000, 145000, 118000, 12, 14.2, '/assets/products/hover1-journey-max.jpg', 'Reliable daily commuter with a built-in Bluetooth speaker for your ride soundtrack. The Journey Max features a 350W motor, 10-inch solid tires that never go flat, and a bright LED headlight and taillight for safe riding in low-light Nigerian conditions.', 1, unixepoch('2026-06-16'), 1, 118000, '/assets/products/hover1-journey-max.jpg', 138000, 4.3, 0, 'Hover-1', 1, 1),

('razor-eco-smart-cargo', 'Razor EcoSmart Cargo Electric Scooter with Rear Basket', 'e-mobility', 280000, 275000, 235000, 6, 28.5, '/assets/products/razor-eco-cargo.jpg', 'Haul groceries, deliveries, or supplies with ease. This cargo scooter features a large rear basket, a wide bamboo deck, and a 500W motor that handles up to 150kg payload. The retro design turns heads while you reduce your carbon footprint.', 1, unixepoch('2026-06-16'), 1, 235000, '/assets/products/razor-eco-cargo.jpg', 258000, 4.4, 0, 'Razor', 1, 1),

('jetson-bolt-pro-folding', 'Jetson Bolt Pro Folding Electric Bike 25km Range - Teal', 'e-mobility', 220000, 215000, 178000, 8, 18.0, '/assets/products/jetson-bolt-pro.jpg', 'A folding electric bike that fits in your car boot. The Bolt Pro features a 350W motor with twist throttle, pedal-assist for longer range, 14-inch wheels, and a lightweight aluminum frame. Arrive at work sweat-free and energized.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/jetson-bolt-pro.jpg', 205000, 4.4, 1, 'Jetson', 1, 1),

('swagtron-swagger-8-boost', 'Swagtron Swagger 8 Boost Electric Scooter with Phone App - Black', 'e-mobility', 135000, 129000, 108000, 14, 12.5, '/assets/products/swagtron-swagger-8.jpg', 'App-connected riding for tech-savvy commuters. The companion app shows speed, battery, and range, while the 300W motor, 8.5-inch honeycomb tires that never puncture, and a 3-hour fast charge make this the smart choice for urban mobility.', 1, unixepoch('2026-06-16'), 1, 108000, '/assets/products/swagtron-swagger-8.jpg', 122000, 4.2, 0, 'Swagtron', 1, 1),

