('withings-body-comp-scale', 'Withings Body Comp Complete Smart Scale with Nerve Health - White', 'health-tech', 185000, 179000, 148000, 8, 2.2, '/assets/products/withings-body-comp.jpg', 'More than a scale—a complete health assessment tool. The Body Comp measures weight, body fat, muscle mass, water percentage, and nerve health via a 6-lead ECG, providing a comprehensive picture of your health with every weigh-in.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/withings-body-comp.jpg', 168000, 4.6, 1, 'Withings', 1, 1),

