('oral-b-io-series-10', 'Oral-B iO Series 10 Electric Toothbrush with AI Brushing Coach', 'health-tech', 125000, 119000, 98000, 12, 0.45, '/assets/products/oralb-io-10.jpg', 'Your personal dentist-approved brushing coach. The iO 10 uses AI to track your brushing in real-time via the interactive display, identifying missed zones and guiding you to a perfect clean. 7 smart modes and 3D teeth tracking ensure nothing is overlooked.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/oralb-io-10.jpg', 112000, 4.7, 1, 'Oral-B', 1, 1),

('philips-sonicare-9900-prestige', 'Philips Sonicare 9900 Prestige SenseIQ Electric Toothbrush', 'health-tech', 165000, 159000, 132000, 8, 0.42, '/assets/products/sonicare-9900.jpg', 'The world''s smartest toothbrush senses and adapts to you. SenseIQ technology detects pressure, motion, and coverage 100 times per second, automatically adjusting intensity for optimal plaque removal without gum damage.', 1, unixepoch('2026-06-16'), 1, 132000, '/assets/products/sonicare-9900.jpg', 149000, 4.7, 0, 'Philips', 1, 1),

('fitbit-sense-3', 'Fitbit Sense 3 Advanced Health Smartwatch - Lunar White', 'wearables', 250000, 245000, 215000, 12, 0.04, '/assets/products/fitbit-sense-3.jpg', 'Your most complete picture of health. The Sense 3 features continuous ECG monitoring for atrial fibrillation, a body-response sensor measuring stress in real-time, skin temperature tracking for illness detection, and SpO2 monitoring during sleep.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/fitbit-sense-3.jpg', 235000, 4.6, 1, 'Fitbit', 1, 1),

('whoop-5-band', 'WHOOP 5.0 Health & Fitness Tracker with 12-Month Membership', 'wearables', 280000, 275000, 235000, 10, 0.02, '/assets/products/whoop-5.jpg', 'Worn by the world''s best athletes to optimize performance. The WHOOP 5.0 measures strain, recovery, and sleep with clinical-grade accuracy, providing personalized insights that tell you exactly how hard to train each day and when to rest.', 1, unixepoch('2026-06-16'), 1, 235000, '/assets/products/whoop-5.jpg', 258000, 4.7, 0, 'WHOOP', 1, 1),

('therabody-smartgoggles-pro', 'Therabody SmartGoggles Pro with Vibration & Heat Therapy', 'health-tech', 165000, 159000, 132000, 8, 0.35, '/assets/products/therabody-goggles-pro.jpg', 'A spa treatment for your eyes and mind. SmartGoggles Pro combines gentle heat, vibration, and SmartRelax mode that monitors your heart rate and adjusts the therapy to reduce stress. The biometric sensor guides you to the deepest relaxation.', 1, unixepoch('2026-06-16'), 1, 132000, '/assets/products/therabody-goggles-pro.jpg', 149000, 4.5, 0, 'Therabody', 1, 1),

