('bluetti-pv350-solar', 'BLUETTI PV350 350W Foldable Solar Panel with Adjustable Stand', 'solar', 320000, 315000, 268000, 5, 13.2, '/assets/products/bluetti-pv350.jpg', 'Premium monocrystalline cells with 23.4% conversion efficiency harvest maximum energy from the Nigerian sun. The PV350 is compatible with most portable power stations via the MC4 connector, with an ETFE coating that extends panel life in harsh weather.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/bluetti-pv350.jpg', 298000, 4.6, 0, 'BLUETTI', 1, 1),

('ecoflow-400w-portable-panel', 'EcoFlow 400W Portable Solar Panel with Auto-Optimizer', 'solar', 420000, 409000, 355000, 4, 16.0, '/assets/products/ecoflow-400w-panel.jpg', 'Charge an EcoFlow power station from 0 to 100% in under 4 hours of direct Nigerian sunlight. The auto-optimizer adjusts voltage and current to maintain peak efficiency even in partial shade, while the IP68 waterproof rating handles sudden rainstorms.', 1, unixepoch('2026-06-16'), 1, 355000, '/assets/products/ecoflow-400w-panel.jpg', 388000, 4.7, 0, 'EcoFlow', 1, 1),

('anker-531-solar-panel', 'Anker 531 Solar Panel 200W with AI Sun-Tracking App - Foldable', 'solar', 250000, 245000, 215000, 7, 9.8, '/assets/products/anker-531-solar.jpg', 'Anker''s first AI-assisted solar panel. The companion app uses your phone camera to find the optimal panel angle for maximum yield, while the 200W monocrystalline array charges Anker SOLIX power stations with 23% conversion efficiency.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/anker-531-solar.jpg', 235000, 4.5, 0, 'Anker', 1, 1),

('allpowers-sp043-400w', 'ALLPOWERS SP043 400W Portable Solar Panel Kit with MPPT Controller', 'solar', 350000, 339000, 288000, 5, 14.5, '/assets/products/allpowers-sp043.jpg', 'A complete solar charging kit including a 400W foldable panel and a 40A MPPT charge controller that''s 30% more efficient than PWM. Compatible with lead-acid and lithium batteries, making it ideal for off-grid cabins, RVs, and backup systems.', 1, unixepoch('2026-06-16'), 1, 288000, '/assets/products/allpowers-sp043.jpg', 318000, 4.4, 0, 'ALLPOWERS', 1, 1),

('sunpower-flex-100w', 'SunPower 100W Flexible Monocrystalline Solar Panel for Vehicles', 'solar', 125000, 119000, 98000, 10, 2.1, '/assets/products/sunpower-flex-100.jpg', 'Ultra-thin at just 2mm, this flexible panel conforms to curved vehicle roofs, boats, and irregular surfaces. SunPower''s Maxeon Gen 7 cells with 25% efficiency are the highest-rated in the industry, backed by a 25-year performance warranty.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/sunpower-flex-100.jpg', 112000, 4.6, 0, 'SunPower', 1, 1);
